def _physical(split, calibration):
    g, b = calibration[split['lab_id']].T
    return (g[:, None] * split['past_stress_cmd'] + b[:, None], g * split['stress_hold_cmd'] + b)

def _fit(data, curves, rates):
    from scipy.optimize import least_squares
    *_, dt, times = data
    target = np.r_[curves.ravel(), rates]
    bounds = (np.full(2, np.log(dt.min() / 30)), np.full(2, np.log(times.max() * 30)))

    def design(log_tau):
        c, r = _design(*data, np.exp(log_tau))
        return np.vstack((c.reshape(-1, 9), r))

    def profile(log_tau, inv_scale):
        a = design(log_tau) * inv_scale[:, None]
        y = target * inv_scale
        w = np.linalg.lstsq(a, y, rcond=None)[0]
        return (np.einsum('ij,j->i', a, w) - y, w)
    unit = np.ones(len(target))
    starts = np.log([[0.15, 1.0], [0.4, 2.5], [0.9, 5.0]])
    best = None
    for start in starts:
        start = np.clip(start, *bounds)
        fit = least_squares(lambda q: profile(q, unit)[0], start, bounds=bounds, max_nfev=100)
        if best is None or fit.cost < best.cost:
            best = fit
    err, weights = profile(best.x, unit)
    taus = np.exp(best.x)
    if taus[0] > taus[1]:
        taus = taus[::-1]
        weights = profile(np.log(taus), unit)[1]
    err = profile(np.log(taus), unit)[0]
    nc = curves.size
    mad = lambda v: max(1e-06, 1.4826 * np.median(np.abs(v - np.median(v))))
    scales = np.r_[np.full(nc, mad(err[:nc])), np.full(len(rates), mad(err[nc:]))]
    lo, hi = bounds

    def residual(p):
        return (np.einsum('ij,j->i', design(p[:2]), p[2:]) - target) / scales
    robust = least_squares(residual, np.r_[np.log(taus), weights], bounds=(np.r_[lo, np.full(9, -np.inf)], np.r_[hi, np.full(9, np.inf)]), loss='cauchy', f_scale=2.5, x_scale='jac', max_nfev=100)
    taus = np.exp(robust.x[:2])
    if taus[0] <= taus[1]:
        return (taus, robust.x[2:])
    taus = taus[::-1]
    return (taus, profile(np.log(taus), 1.0 / scales)[1])

def _channel(sweep, lab):
    x = np.asarray(sweep['cmd_stress'], dtype=float)
    y = np.asarray(sweep['true_stress'], dtype=float)
    use = (np.asarray(sweep['lab_id']) == lab) & np.isfinite(x) & np.isfinite(y)
    return (x[use], y[use])

def _basis(past, hold, dt, times, taus):
    later = np.r_[np.cumsum(dt[:0:-1])[::-1], 0.0]
    memory_weights = -np.expm1(-dt[:, None] / taus) * np.exp(-later[:, None] / taus)
    gap = hold[:, None] - past @ memory_weights
    response = -np.expm1(-times[:, None] / taus)
    return (gap[:, None, :] * response, gap / taus)
